"""Imagens do onboarding (Tela 1 — Seu Perfil), recortadas da referência aprovada. Só dados: WebP em base64."""

IMAGENS = {
    "mascote": "",
    "arrojado": "",
    "equilibrado": "",
    "conservador": "",
    "iniciante": "",
    "explorador": "",
}


def uri(nome: str) -> str:
    d = IMAGENS.get(nome)
    return f"data:image/webp;base64,{d}" if d else ""


def existe(nome: str) -> bool:
    return nome in IMAGENS
